import { useRef } from 'react';

import Timings from '@dynatrace/strato-design-tokens/timings-js';

import { CanvasDraw } from '../types/canvas-shape.js';

const ANIMATION_DURATION = Timings.Base.Default * 1000;

type DatumData<Datum> = {
  data: Datum[];
};

export function useCanvasAnimation<T extends DatumData<E>, E>(
  initialCanvas: T,
  drawEntireShape: (ctx: CanvasRenderingContext2D, prevCanvas: T) => void,
  animated: boolean,
  isCanvasEqual: (canvas: T, prevCanvas: T) => boolean,
  tickAnimationDraw: (
    progress: number,
    ctx: CanvasRenderingContext2D,
    canvas: T,
    prevCanvas?: T,
  ) => void,
  timeAnimation: number = ANIMATION_DURATION,
) {
  const prevCanvasRef = useRef<T>();
  const canvasRef = useRef<T>(initialCanvas);
  const initialTimestampRef = useRef<number | null>(null);

  canvasRef.current = initialCanvas;

  const draw: CanvasDraw = (
    ctx: CanvasRenderingContext2D,
    timestamp?: number,
  ): boolean => {
    const prevCanvas = prevCanvasRef.current;
    const hasData = canvasRef.current.data.length > 0;

    if (!hasData) {
      prevCanvasRef.current = canvasRef.current;
      initialTimestampRef.current = null;

      return false;
    }

    const isAnimated =
      initialTimestampRef.current ??
      (animated &&
        (!prevCanvas || !isCanvasEqual(canvasRef.current, prevCanvas)));

    if (isAnimated && timestamp) {
      if (initialTimestampRef.current === null) {
        initialTimestampRef.current = timestamp;
      }

      const progress =
        (timestamp - initialTimestampRef.current) / timeAnimation;

      const animationFinished = progress > 1;

      !animationFinished &&
        tickAnimationDraw(progress, ctx, canvasRef.current, prevCanvas);

      if (animationFinished) {
        prevCanvasRef.current = canvasRef.current;
        initialTimestampRef.current = null;
        drawEntireShape(ctx, canvasRef.current);

        return false;
      }

      return true;
    }

    drawEntireShape(ctx, canvasRef.current);
    prevCanvasRef.current = canvasRef.current;

    return false;
  };

  return { draw };
}
